-- Lot 203 : payloads 61 a 90 sur 150.
--
-- Un texte propre a chaque IA. Les commandes etant neuves, aucune version
-- courante n'existe : rien n'est retire, tout est pose.

drop table if exists lot_extension_payloads;
create temporary table lot_extension_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-401","moteur":"chatgpt","payload":"[RaccourcIA — /scrapbookdump]\n\nMISSION\nAssemblez plusieurs images en collage scrapbook organique avec rubans, notes et détails tactiles. Composer un collage tactile avec photos superposées, papier, ruban, griffonnages et quelques mots décoratifs inventés si aucun texte exact n’est demandé.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque pièce jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Si une information indispensable manque, pose UNE seule question à la fois, dans cet ordre conditionnel : Quel souvenir ou thème doit relier les images du scrapbook ?. Après chaque réponse, réanalyse et produis dès que possible. Accepte « Choisis pour moi » pour toute préférence non critique.\n\nEXÉCUTION\nComposer un collage tactile avec photos superposées, papier, ruban, griffonnages et quelques mots décoratifs inventés si aucun texte exact n’est demandé. Format par défaut : 4:5, haute définition. Si plusieurs images sont demandées, maintiens une continuité stricte entre elles. Si du texte exact est fourni, reproduis-le fidèlement; si le texte n’est pas indispensable, préfère une sortie sans texte.\n\nTEXTE DANS L’IMAGE\nSi l’utilisateur ne fournit pas de texte exact et que le concept en nécessite, tu peux créer uniquement du micro-texte simple, décoratif et manifestement fictif. N’invente jamais une vraie citation, un vrai classement, une récompense, un prix, une certification, une transaction, une fonction officielle ou une affirmation sensible. N’utilise pas le logo ou la maquette exacte d’un média réel.\n\nPRÉSERVER\nChaque image source, visages, éléments principaux et ordre demandé.\n\nÉVITER\nTexte factuel inventé, visage recoupé maladroitement, surcharge, éléments décoratifs dominant les photos. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nProduis l’image finale, pas un tutoriel. Vérifie silencieusement sujet, identité ou géométrie, proportions, perspective, lumière, ombres, matières, texte, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique clairement que l’image n’a pas été générée.","sha256":"fb75808c0d871fcf9eb60892bc893e6b0ff80ba7a79e4221c7c54ad7a8738eec"},{"ref":"RCI-IMG-401","moteur":"claude","payload":"[RaccourcIA — /scrapbookdump]\n\nMISSION\nAssemblez plusieurs images en collage scrapbook organique avec rubans, notes et détails tactiles. Composer un collage tactile avec photos superposées, papier, ruban, griffonnages et quelques mots décoratifs inventés si aucun texte exact n’est demandé.\n\nDÉCISION\nExamine d’abord toutes les images et documents, puis consolide les contraintes sans longue reformulation. Vérifie les capacités réellement disponibles avant de produire. Si le contexte suffit, exécute directement. Ne questionne jamais sur une information visible ou déjà fournie. Si un choix bloquant reste inconnu, pose UNE seule question à la fois : Quel souvenir ou thème doit relier les images du scrapbook ?. Réévalue après chaque réponse; « Choisis pour moi » autorise une décision professionnelle sur les préférences secondaires.\n\nEXÉCUTION\nComposer un collage tactile avec photos superposées, papier, ruban, griffonnages et quelques mots décoratifs inventés si aucun texte exact n’est demandé. Format par défaut : 4:5, haute définition. Si plusieurs images sont demandées, maintiens une continuité stricte entre elles. Si du texte exact est fourni, reproduis-le fidèlement; si le texte n’est pas indispensable, préfère une sortie sans texte.\n\nTEXTE DANS L’IMAGE\nSi l’utilisateur ne fournit pas de texte exact et que le concept en nécessite, tu peux créer uniquement du micro-texte simple, décoratif et manifestement fictif. N’invente jamais une vraie citation, un vrai classement, une récompense, un prix, une certification, une transaction, une fonction officielle ou une affirmation sensible. N’utilise pas le logo ou la maquette exacte d’un média réel.\n\nPRÉSERVER\nChaque image source, visages, éléments principaux et ordre demandé.\n\nÉVITER\nTexte factuel inventé, visage recoupé maladroitement, surcharge, éléments décoratifs dominant les photos. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nProduis l’image finale, pas un tutoriel. Vérifie silencieusement sujet, identité ou géométrie, proportions, perspective, lumière, ombres, matières, texte, recadrage et artefacts; corrige ce qui peut l’être. Sans moteur image connecté, livre un brief de transfert autonome, précis et directement exploitable; ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"b1fee2ccad804446ccddead8f3e54dc67c3871919ff66fec9562ab8242bfee80"},{"ref":"RCI-IMG-401","moteur":"gemini","payload":"[RaccourcIA — /scrapbookdump]\n\nMISSION\nAssemblez plusieurs images en collage scrapbook organique avec rubans, notes et détails tactiles. Composer un collage tactile avec photos superposées, papier, ruban, griffonnages et quelques mots décoratifs inventés si aucun texte exact n’est demandé.\n\nDÉCISION\nInspecte visuellement toutes les références avant le texte de contexte et attribue à chacune son rôle : sujet, style, données ou composition. Si les éléments indispensables sont présents, génère immédiatement. Ne redemande jamais ce qui est visible ou déjà connu. Si une décision critique manque, pose UNE seule question à la fois : Quel souvenir ou thème doit relier les images du scrapbook ?. Après la réponse, exécute dès que le contexte devient suffisant; « Choisis pour moi » permet de décider les préférences créatives secondaires.\n\nEXÉCUTION\nComposer un collage tactile avec photos superposées, papier, ruban, griffonnages et quelques mots décoratifs inventés si aucun texte exact n’est demandé. Format par défaut : 4:5, haute définition. Si plusieurs images sont demandées, maintiens une continuité stricte entre elles. Si du texte exact est fourni, reproduis-le fidèlement; si le texte n’est pas indispensable, préfère une sortie sans texte.\n\nTEXTE DANS L’IMAGE\nSi l’utilisateur ne fournit pas de texte exact et que le concept en nécessite, tu peux créer uniquement du micro-texte simple, décoratif et manifestement fictif. N’invente jamais une vraie citation, un vrai classement, une récompense, un prix, une certification, une transaction, une fonction officielle ou une affirmation sensible. N’utilise pas le logo ou la maquette exacte d’un média réel.\n\nPRÉSERVER\nChaque image source, visages, éléments principaux et ordre demandé.\n\nÉVITER\nTexte factuel inventé, visage recoupé maladroitement, surcharge, éléments décoratifs dominant les photos. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nProduis l’image finale, pas un tutoriel. Vérifie silencieusement sujet, identité ou géométrie, proportions, perspective, lumière, ombres, matières, texte, recadrage et artefacts; corrige ce qui peut l’être. Si la génération ou l’édition visuelle n’est pas disponible, livre un prompt final compatible avec un moteur d’image et précise le statut réel de la sortie.","sha256":"51f3cf3431f8b9a67561a3ddd9bbbb9f591a7d27a1e1812cf80c271fad42758b"},{"ref":"RCI-IMG-402","moteur":"chatgpt","payload":"[RaccourcIA — /scribbleoverlay]\n\nMISSION\nAjoutez des dessins spontanés, flèches, étoiles et mots courts autour du sujet. Ajouter des tracés à main levée cohérents avec les contours et l’espace négatif, avec mots très courts uniquement s’ils sont fournis ou clairement décoratifs.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque pièce jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Si une information indispensable manque, pose UNE seule question à la fois, dans cet ordre conditionnel : Voulez-vous des griffonnages minimalistes ou très expressifs ?. Après chaque réponse, réanalyse et produis dès que possible. Accepte « Choisis pour moi » pour toute préférence non critique.\n\nEXÉCUTION\nAjouter des tracés à main levée cohérents avec les contours et l’espace négatif, avec mots très courts uniquement s’ils sont fournis ou clairement décoratifs. Format par défaut : 4:5, haute définition. Si plusieurs images sont demandées, maintiens une continuité stricte entre elles. Si du texte exact est fourni, reproduis-le fidèlement; si le texte n’est pas indispensable, préfère une sortie sans texte.\n\nTEXTE DANS L’IMAGE\nSi l’utilisateur ne fournit pas de texte exact et que le concept en nécessite, tu peux créer uniquement du micro-texte simple, décoratif et manifestement fictif. N’invente jamais une vraie citation, un vrai classement, une récompense, un prix, une certification, une transaction, une fonction officielle ou une affirmation sensible. N’utilise pas le logo ou la maquette exacte d’un média réel.\n\nPRÉSERVER\nSujet, visage, lisibilité, zones importantes et hiérarchie de la photo.\n\nÉVITER\nDessins sur les yeux ou informations clés, longs textes, symboles offensants, style trop propre. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nProduis l’image finale, pas un tutoriel. Vérifie silencieusement sujet, identité ou géométrie, proportions, perspective, lumière, ombres, matières, texte, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n